import { Button, Tooltip } from "@heroui/react"
import React from 'react'
import { useStateContext } from '../../contexts/ContextProvider'

export default function Seat({ handleSelectAction, selectedSeats, seat,trip }) {
    const {currentColor}=useStateContext()
    const isSeatSold=(seat)=>trip.sold_seats.includes(seat)
    const isStaffSeat=(seat)=>trip.staff_seats.includes(seat)
    const isSelected=(seat)=>selectedSeats.includes(seat)


    return (
        <div key={seat} className='items-center justify-center flex flex-col' v>  <Tooltip  size={24} content={seat}>


            {seat && seat ==="H"?<div></div> :<div  onClick={()=>handleSelectAction(seat, isSeatSold(seat))} style={{
                background: isSeatSold(seat)?"red": isSelected(seat)?"grey":currentColor,cursor: isSeatSold(seat)?"": "pointer"
                
               
                
            }} className="text-lg text-default-400 cursor-pointer active:opacity-50  text-center w-16 h-16 m-5 justify-center items-center flex border-r-1  ">
                
                <p  disabled={isSeatSold} className='text-white font-semibold text-lg'>{seat}</p>
            </div>}
        </Tooltip></div>

    )
}
